# ── v2 completion (24 Nov 2026): second worked scenario and a sixth taught section ──
def _sec(sid):
    return next(s for s in MODULE["sections"] if s["id"] == sid)

_sec("vnd")["html"] += """
<div class="tc-scene"><span class="tc-lab">Station 9, 2:15 a.m. &middot; fictional</span><p>Night shift. Mr. Arnel Bautista, 71, has mild dementia and is dialyzing through a left upper-arm fistula at a blood flow of 350 mL/min. He has pulled at his lines twice tonight. The venous pressure reads 140 mmHg; the alarm limits are set 40 mmHg either side. Nurse Joy, on her round, sees a dark patch spreading on the sheet under his elbow. The venous needle is lying beside the arm, still taped to the line. The venous pressure now reads 115 mmHg. No alarm has sounded.</p><p>She stops the blood pump, clamps the venous line and the needle, presses on the site with gauze, and calls the charge nurse and the physician on duty. She checks his blood pressure, pulse and level of alertness, and estimates the blood on the sheet. She has the blood loss assessed by the physician, who decides on blood tests and whether to continue treatment. She writes the times, the pressures before and after, and the taping method, and files an incident report that shift.</p><p>At the next safety huddle, Joy brings the pattern, not the person: a restless patient, an access under a sleeve, an alarm that fell only 25 mmHg. The unit agrees on a plan for high-risk patients (visible access, extra anchoring loop, a station closer to the nurses' desk, rounds every 15 minutes) and she adds it to the hazard-round checklist.</p><p class="tc-scene-take"><b>What this shows.</b> The pressure fell, but not enough to cross the limit, exactly as the physiology predicts. Eyes on the site caught what the machine did not. The response came first; the system fix followed.</p></div>
"""

_drills = {"id": "drills", "nav": "Drills that teach", "tag": "Practice", "h2": "Run drills that change what people do",
 "html": """
<p>A drill is a test of the plan, not a performance for an inspector. A drill that goes perfectly has usually tested too little. The aim is to find the gaps (the missing clamp, the phone number nobody updated, the nurse who has never returned blood by hand) while no patient is at risk.</p>
<div class="table-wrap"><table>
<thead><tr><th>Drill type</th><th>How it runs</th><th>What it can show</th></tr></thead>
<tbody>
<tr><td>Tabletop</td><td>Staff talk through a scenario at a table, step by step, with the written plan open</td><td>Gaps in the plan, unclear roles, missing contacts</td></tr>
<tr><td>Skills station</td><td>Each nurse performs emergency disconnection or manual blood return on an unconnected machine</td><td>Who cannot yet do it; machine-specific differences</td></tr>
<tr><td>Unannounced functional drill</td><td>A scenario called mid-shift (for example, "power is out at station row B"), with an observer and a stopwatch, without disconnecting real patients</td><td>Time to uncover every access, account for every patient, reach the physician and the technician</td></tr>
</tbody></table></div>
<p><strong>Debrief within the hour.</strong> Ask three questions: what was supposed to happen, what actually happened, and what we will change. Record each change with an owner and a check date, and test it at the next drill.</p>
<p><strong>Include the patients.</strong> Patients should know what to do in an earthquake while connected, which unit to go to if theirs is closed, and how to follow an emergency diet when a session is missed. Teach it in small parts over several sessions and check with teach-back (Module 5).</p>
<div class="tc-scene"><span class="tc-lab">The four-minute drill &middot; fictional</span><p>Nurse Ronnie runs an unannounced power-failure drill at 10 a.m. with the charge nurse's agreement. The observer times how long it takes until every access site is uncovered and every station has its disconnection card in hand. Most stations take under a minute. Station 14 takes four minutes: the nurse there had been pulled to help with a transfusion, and nobody covered her patients.</p><p>The debrief does not blame her. The unit adds a rule: in any alarm event, the charge nurse names who covers each empty station. At the next drill, the slowest station takes 70 seconds.</p><p class="tc-scene-take"><b>What this shows.</b> The gap was in coverage, not in skill. Only a timed drill could find it, and only a repeat drill could show that the fix worked.</p></div>
<div class="tc-stop"><span class="tc-lab">Never</span>Run a drill that disconnects or interrupts a real patient's treatment, or silence live alarms to make a drill look smoother.</div>
"""}
MODULE["sections"].insert([s["id"] for s in MODULE["sections"]].index("respond"), _drills)
